CREATE OR REPLACE FUNCTION place_order(p_cid bigint, p_pid bigint, p_qty integer, p_discount numeric)
RETURNS bigint LANGUAGE plpgsql AS $$
DECLARE v_oid bigint; v_price numeric(12,2); v_stock integer;
BEGIN
  IF p_qty <= 0 OR p_discount < 0 OR p_discount > 1 THEN
    RAISE EXCEPTION 'invalid input';
  END IF;
  PERFORM 1 FROM customer WHERE customer_id=p_cid AND status='ACTIVE';
  IF NOT FOUND THEN RAISE EXCEPTION 'customer not active'; END IF;
  SELECT unit_price, stock_qty INTO v_price,v_stock
  FROM product WHERE product_id=p_pid FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'product not found'; END IF;
  IF v_stock < p_qty THEN RAISE EXCEPTION 'not enough stock'; END IF;
  INSERT INTO orders(customer_id,ordered_at,total_amount,status)
  VALUES(p_cid,CURRENT_TIMESTAMP,v_price*p_qty*(1-p_discount),'PLACED')
  RETURNING order_id INTO v_oid;
  INSERT INTO order_item VALUES(v_oid,p_pid,p_qty,v_price,p_discount);
  UPDATE product SET stock_qty=stock_qty-p_qty WHERE product_id=p_pid;
  RETURN v_oid;
END; $$;

It is called in one transaction. An uncaught exception rolls the transaction back, so it is atomic. Checks and constraints give consistency. FOR UPDATE makes concurrent orders wait on the product row and prevents both seeing the same stock. PostgreSQL WAL makes committed data durable.

