CREATE FUNCTION place_order(cid bigint,pid bigint,qty int,disc numeric) RETURNS bigint AS $$
DECLARE oid bigint; price numeric; available int;
BEGIN
 IF qty<=0 OR disc<0 OR disc>1 THEN RAISE EXCEPTION 'bad input'; END IF;
 PERFORM 1 FROM customer WHERE customer_id=cid AND status='ACTIVE';
 IF NOT FOUND THEN RAISE EXCEPTION 'bad customer'; END IF;
 SELECT unit_price,stock_qty INTO price,available FROM product WHERE product_id=pid FOR UPDATE;
 IF available<qty THEN RAISE EXCEPTION 'no stock'; END IF;
 INSERT INTO orders(customer_id,ordered_at,total_amount,status)
 VALUES(cid,now(),price*qty*(1-disc),'PLACED') RETURNING order_id INTO oid;
 INSERT INTO order_item VALUES(oid,pid,qty,price,disc);
 UPDATE product SET stock_qty=stock_qty-qty WHERE product_id=pid;
 RETURN oid;
END $$ LANGUAGE plpgsql;

The row lock stops two buyers using the same quantity and PostgreSQL rolls back on an error. This gives atomicity and isolation, the checks help consistency, and commit/WAL gives durability. I should also explicitly test NOT FOUND after selecting the product.

