CREATE FUNCTION place_order(c bigint,p bigint,q int,d numeric) RETURNS bigint AS $$
DECLARE id bigint; pr numeric; st int;
BEGIN
 IF q<=0 OR d<0 OR d>1 THEN RAISE EXCEPTION 'invalid'; END IF;
 IF NOT EXISTS(SELECT 1 FROM customer WHERE customer_id=c AND status='ACTIVE') THEN RAISE EXCEPTION 'customer'; END IF;
 SELECT unit_price,stock_qty INTO pr,st FROM product WHERE product_id=p FOR UPDATE;
 IF st<q THEN RAISE EXCEPTION 'stock'; END IF;
